/**
 * In-memory transport for routing Raft messages between RaftNode instances
 * within the same process. This is useful for tests and examples.
 *
 * Usage:
 *   const t = new InMemoryTransport();
 *   const n1 = new RaftNode({ id: '1', peers: ['1','2','3'], transport: t, ... });
 *   const n2 = new RaftNode({ id: '2', peers: ['1','2','3'], transport: t, ... });
 *   const n3 = new RaftNode({ id: '3', peers: ['1','2','3'], transport: t, ... });
 *   await n1.start(); await n2.start(); await n3.start();
 */
export class InMemoryTransport {
  constructor() {
    // id (string) -> RaftNode
    this._nodes = new Map();
    this._pending = 0;
  }

  /**
   * Returns the total number of pending messages currently being processed.
   */
  pendingCount() {
    return this._pending;
  }

  /**
   * Waits until all pending messages have been processed.
   */
  async flush() {
    while (this._pending > 0) {
      await new Promise((r) => setImmediate(r));
    }
  }

  /**
   * Register a node instance so messages addressed to its ID can be delivered.
   * RaftNode.start() will call transport.register(this) automatically.
   */
  register(node) {
    if (!node || !node.id) {
      throw new Error('register(node) requires a node with an id');
    }
    this._nodes.set(String(node.id), node);
  }

  /**
   * Send a batch of Raft messages. Each message is plain JSON in the WASM boundary
   * schema with u64 fields represented as strings. We route based on msg.to.
   * @param {string} fromId
   * @param {Array<object>} msgs
   */
  async send(fromId, msgs) {
    for (const m of msgs || []) {
      const to = m.to != null ? String(m.to) : undefined;
      if (!to) continue;
      const dest = this._nodes.get(to);
      if (!dest) {
        // Drop if destination not registered; real transports might queue/retry
        continue;
      }
      // Deliver to destination node. step() handles applying and generating further Ready as needed.
      this._pending++;
      try {
        await dest.step(m);
      } finally {
        this._pending--;
      }
    }
  }

  /**
   * Client request helper for auto-forwarding to leader.
   * This is a best-effort in-memory convenience used by ThreadedRaftNode.clientRequest().
   * @param {string} leaderId
   * @param {Uint8Array|ArrayBuffer|string} data
   * @param {{ waitFor?: 'none'|'commit'|'apply', timeout?: number, abortSignal?: AbortSignal }} [opts]
   * @returns {Promise<{index:number, term:number}>}
   */
  async sendClientRequest(leaderId, data, opts = {}) {
    const dest = this._nodes.get(String(leaderId));
    if (!dest) {
      const e = new Error(`Leader ${leaderId} not registered in transport`);
      e.code = 'NoRoute';
      throw e;
    }
    if (typeof dest.clientRequest === 'function') {
      return await dest.clientRequest(data, opts);
    }
    // Fallback if node doesn't implement clientRequest:
    // - try propose() and optionally emulate waitFor using status polling (best-effort)
    if (typeof dest.propose !== 'function') {
      const e = new Error('Destination node does not support clientRequest or propose');
      e.code = 'Unsupported';
      throw e;
    }
    await dest.propose(data);
    // If the destination exposes waitForCommit (ThreadedRaftNode does), use it.
    const result = { index: undefined, term: undefined };
    try {
      if (typeof dest.status === 'function') {
        const st = await dest.status();
        if (st && typeof st.term === 'number') result.term = st.term;
        // Cannot know index without introspection; caller may still wait via waitForCommit if available.
      }
      if (opts && opts.waitFor && typeof dest.waitForCommit === 'function' && typeof dest.status === 'function') {
        // Snapshot commit/apply target after propose by checking status twice with a brief microtask delay
        const s1 = await dest.status();
        const target = (s1 && typeof s1.lastLogIndex === 'number') ? s1.lastLogIndex : undefined;
        if (typeof target === 'number' && target > 0) {
          await dest.waitForCommit(target, { localApply: opts.waitFor === 'apply', timeout: opts.timeout, abortSignal: opts.abortSignal });
          result.index = target;
        }
      }
    } catch (err) {
      throw err;
    }
    return result;
  }
}
